input.content:
workspace "Energy Manager" "C4 model of the Energy Manager home energy management platform." {
    model {
        homeowner = person "Homeowner" "Uses the platform to manage the household's energy use and costs."

        energyManager = softwareSystem "Energy Manager" "Platform for managing a household's energy use and costs, owned and operated by our company." {
            dashboard = container "Dashboard Web App" "Web app where homeowners see consumption and costs. Embeds the shared rates library, which computes energy prices from tariff and time of day." "Web application"
            scheduler = container "Scheduling Service" "Service that plans charging and heating. Embeds the shared rates library, which computes energy prices from tariff and time of day." "Service"
            database = container "Database" "Stores meter readings and schedules." "Database"
        }

        smartMeterProvider = softwareSystem "Smart Meter Provider" "Provides live meter readings. Operated by a different organization." "External"

        homeowner -> dashboard "views consumption and costs" "HTTPS/JSON"
        scheduler -> smartMeterProvider "fetches live meter readings" "HTTPS/JSON"
        scheduler -> database "stores meter readings and schedules" "SQL"
    }

    views {
        systemContext energyManager "Energy Manager - System Context" "System context diagram showing the Energy Manager system, its users, and the external systems it interacts with." {
            include *
            autoLayout
        }

        container energyManager "Energy Manager - Containers" "Container diagram showing the internal containers of the Energy Manager system." {
            include *
            autoLayout
        }
    }
}

